// Shared, non-reactive receivers; usable in Node and injected Vue component methods.
function createMeterReceiver (manifest) {
  const number = value => typeof value === 'number' && Number.isFinite(value)
  if (manifest?.kind !== 'meter-manifest' || typeof manifest.streamId !== 'string' ||
    !manifest.streamId.trim() || manifest.streamId.length > 255 ||
    typeof manifest.epoch !== 'string' || !manifest.epoch || manifest.epoch.length > 128 ||
    !Number.isInteger(manifest.layoutVersion) || manifest.layoutVersion < 1 ||
    manifest.layoutVersion > 2147483647 || manifest.clock !== 'monotonic-ms' ||
    !number(manifest.publishHz) || manifest.publishHz < 1 || manifest.publishHz > 60 ||
    !Array.isArray(manifest.points) || !manifest.points.length || manifest.points.length > 256) {
    throw Error('Invalid meter manifest')
  }
  const paths = new Set()
  const points = Array.from(manifest.points, point => {
    if (typeof point?.path !== 'string' || !/^\/[^/]/.test(point.path) ||
      point.path.length > 1025 || paths.has(point.path) ||
      !['integer', 'float'].includes(point.type) || !number(point.min) ||
      !number(point.max) || point.min >= point.max ||
      (point.type === 'integer' && (!Number.isSafeInteger(point.min) || !Number.isSafeInteger(point.max))) ||
      typeof point.unit !== 'string' || point.unit.length > 32) throw Error('Invalid meter point')
    paths.add(point.path)
    return Object.freeze({ path: point.path, type: point.type, min: point.min, max: point.max, unit: point.unit })
  })
  const schema = Object.freeze({ ...manifest, points: Object.freeze(points) })
  let latest = null, pending = false, closed = false
  return {
    manifest: schema,
    accept (frame) {
      if (closed || frame?.kind !== 'meter-frame' || frame.streamId !== schema.streamId ||
        frame.epoch !== schema.epoch || frame.layoutVersion !== schema.layoutVersion ||
        !Number.isSafeInteger(frame.seq) || frame.seq < 1 || (latest && frame.seq <= latest.seq) ||
        !number(frame.sampleTime) || frame.sampleTime < 0 ||
        !Array.isArray(frame.values) || frame.values.length !== points.length ||
        !Array.isArray(frame.valid) || frame.valid.length !== points.length) return false
      const values = [], valid = []
      for (let index = 0; index < points.length; index++) {
        const point = points[index], value = frame.values[index], flag = frame.valid[index]
        if (typeof flag !== 'boolean' || (flag && (!number(value) ||
          value < point.min || value > point.max ||
          (point.type === 'integer' && !Number.isSafeInteger(value))))) return false
        values.push(flag ? value : null)
        valid.push(flag)
      }
      latest = Object.freeze({ kind: 'meter-frame', streamId: schema.streamId,
        epoch: schema.epoch, seq: frame.seq, layoutVersion: schema.layoutVersion,
        sampleTime: frame.sampleTime, values: Object.freeze(values), valid: Object.freeze(valid) })
      pending = true
      return true
    },
    snapshot () { return latest },
    take () {
      if (!pending) return null
      pending = false
      return latest
    },
    close () { closed = true; pending = false; latest = null }
  }
}

function createMeterRenderer ({ receiver, requestFrame, cancelFrame, apply }) {
  let handle = null, closed = false
  return {
    receive (frame) {
      if (closed || !receiver.accept(frame)) return false
      if (handle === null) {
        handle = requestFrame(() => {
          handle = null
          const current = receiver.take()
          if (!closed && current) apply(current)
        })
      }
      return true
    },
    close () {
      closed = true
      if (handle !== null) cancelFrame(handle)
      handle = null
      receiver.close()
    }
  }
}

function createRoomMeterReceiver (layout) {
  if (layout?.kind !== 'room-meter-layout' || typeof layout.panelId !== 'string' ||
    typeof layout.room !== 'string' || typeof layout.epoch !== 'string' || !layout.epoch ||
    !Array.isArray(layout.ids) || !layout.ids.length || layout.ids.length > 256 ||
    layout.ids.some(id => typeof id !== 'string' || !id) || new Set(layout.ids).size !== layout.ids.length) {
    throw Error('Invalid Room meter layout')
  }
  let latest = null, pending = false, closed = false
  const count = layout.ids.length
  return {
    accept (frame) {
      if (closed || frame?.kind !== 'room-meter-frame' || frame.panelId !== layout.panelId ||
        frame.room !== layout.room || frame.epoch !== layout.epoch ||
        !Number.isSafeInteger(frame.seq) || frame.seq < 1 || (latest && frame.seq <= latest.seq) ||
        !Array.isArray(frame.values) || frame.values.length !== count ||
        !Array.isArray(frame.valid) || frame.valid.length !== count ||
        frame.valid.some((flag, index) => typeof flag !== 'boolean' || (flag
          ? typeof frame.values[index] !== 'number' || !Number.isFinite(frame.values[index])
          : frame.values[index] !== null))) return false
      if (frame.sources !== undefined && (!Array.isArray(frame.sources) || frame.sources.length > 256 ||
        frame.sources.some(source => typeof source?.device !== 'string' || source.device.length > 128 ||
          typeof source.streamId !== 'string' || source.streamId.length > 128 ||
          typeof source.epoch !== 'string' || source.epoch.length > 128 ||
          !Number.isSafeInteger(source.seq) || source.seq < 0))) return false
      latest = { values: frame.values.slice(), valid: frame.valid.slice(), seq: frame.seq,
        ...(frame.sources ? { sources: frame.sources.map(({ device, streamId, epoch, seq }) => ({ device, streamId, epoch, seq })) } : {}) }
      pending = true
      return true
    },
    take () { if (!pending) return null; pending = false; return latest },
    close () { closed = true; latest = null; pending = false }
  }
}

module.exports = { createMeterReceiver, createMeterRenderer, createRoomMeterReceiver }
